for (u,v,t) in events:
    if start <= t <= end:
        by_pair[(u,v)].append(t)
        by_src[u].append((v,t))

# 1) interactions among entity_list within window
print('Interactions among entity_list within window:')
for i,u in enumerate(entity_list):
    for v in entity_list[i+1:]:
        times = by_pair.get((u,v),[]) + by_pair.get((v,u),[])
        if times:
            print(u,v,sorted(times))

# 2) common neighbor supports in window for each pair
print('\nCommon-neighbor supporting interactions in window (u->w and v->w):')
nodes_seen = set()
for (u,v,t) in events:
    if start<=t<=end:
        nodes_seen.add(u); nodes_seen.add(v)

for i,u in enumerate(entity_list):
    for v in entity_list[i+1:]:
        common_ws = set()
        for w in nodes_seen:
            if w==u or w==v: continue
            t_us = [t for (x,t) in by_src[u] if x==w]
            t_vs = [t for (x,t) in by_src[v] if x==w]
            if t_us and t_vs:
                common_ws.add(w)
                print(f'Pair {u}-{v} common w={w} u->w times={sorted(t_us)} v->w times={sorted(t_vs)}')

# 3) For each found common w, show u-v interactions overall and whether any occur within 800 of max(t_us,t_vs)
print('\nCheck closings relative to supports:')
for i,u in enumerate(entity_list):
    for v in entity_list[i+1:]:
        for w in nodes_seen:
            if w==u or w==v: continue
            t_us = [t for (x,t) in by_src[u] if x==w]
            t_vs = [t for (x,t) in by_src[v] if x==w]
            if not (t_us and t_vs): continue
            for t1 in t_us:
                for t2 in t_vs:
                    t_common = max(t1,t2)
                    # all u-v events in entire log
                    uv_times = [t for (a,b,t) in events if (a==u and b==v) or (a==v and b==u)]
                    uv_after = [t for t in uv_times if t>=t_common and t<=t_common+800]
                    uv_in_window_after = [t for t in uv_after if start<=t<=end]
                    print(f'u={u},v={v},w={w},t1={t1},t2={t2},t_common={t_common},uv_after={sorted(uv_after)},uv_in_window_after={sorted(uv_in_window_after)}')

print('\nDone')

